sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    response.setContentType('application/json');
    try {
        if (!gs.hasRole('x_2316161_bjit_e_0.employee'))
            throw { status: 403, code: 'forbidden', message: 'You do not have permission to reject leave requests.' };
        var id = request.pathParams.id;
        var body = request.body.data || {};
        var result = new x_2316161_bjit_e_0.BjitLeaveApproval().reject(id, body.comments);
        response.setStatus(200);
        response.setBody(result);
    } catch (e) {
        if (e && e.status && e.code) {
            response.setStatus(e.status);
            response.setBody({ code: e.code, message: e.message });
        } else {
            gs.error('BJIT leave reject failed: ' + e);
            response.setStatus(500);
            response.setBody({ code: 'reject_failed', message: 'This decision could not be saved. Please try again.' });
        }
    }
})(request, response);
